import { AfterViewInit, Component, Input, OnInit, Optional, Self, ViewEncapsulation } from '@angular/core';
import { NgClass, NgIf } from '@angular/common';
import { MAT_FORM_FIELD_DEFAULT_OPTIONS, MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInput, MatInputModule } from '@angular/material/input';
import { FormGroupDirective, FormsModule, NgControl, NgForm } from '@angular/forms';
import { MatTooltipModule } from '@angular/material/tooltip';
import { coerceBooleanProperty } from '@angular/cdk/coercion';
import { A11yModule } from '@angular/cdk/a11y';

import { BaseComponent } from 'sidsc-components/core';
import { DscTooltipModule } from 'sidsc-components/dsc-tooltip';


@Component({
  selector: 'dsc-textarea',
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  imports: [
    NgIf,
    NgClass,
    FormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatIconModule,
    MatTooltipModule,
    DscTooltipModule,
    A11yModule
  ],
  providers: [{ provide: MAT_FORM_FIELD_DEFAULT_OPTIONS, useValue: { appearance: 'outline' } }],
  templateUrl: './dsc-textarea.component.html',
  styleUrls: ['./dsc-textarea.component.scss']
})
export class DscTextareaComponent extends BaseComponent<string> implements OnInit, AfterViewInit {
  matInput!: MatInput;

  @Input()
  get showCharCounter(): boolean {
    return this._showCharCounter;
  }

  @Input('aria-describedby') override ariaDescribedby!: string;

  set showCharCounter(value: boolean | string) {
    this._showCharCounter = coerceBooleanProperty(value);
  }

  private _showCharCounter = false;

  isActive: boolean = false;

  tooltipId = `tt-${cryptoRandom()}`;

  constructor(@Optional() @Self() public ngControl: NgControl,
              @Optional() parentForm: NgForm,
              @Optional() parentFormGroup: FormGroupDirective
  ) {
    super(ngControl, parentForm, parentFormGroup);
    if (ngControl) ngControl.valueAccessor = this;
  }

  ngOnInit(): void {
    this.updateOn = this.ngControl?.control?.updateOn;
  }

  ngAfterViewInit(): void {
    
    // const ids: string[] = [];
    // if (this.labelHintTooltip) ids.push(this.tooltipId);
    // if (this.formFieldHint) ids.push(this.hintId);

    // this.matInput.setDescribedByIds(ids);

  }

  get formFieldClasses(): string[] {
    return [
      this.ngControl && this.ngControl.value?.length
        ? 'mat-mdc-form-field--filled'
        : 'mat-mdc-form-field--empty',
      this.readOnly ? 'mat-mdc-form-field--readonly' : '',
      this.ngControl &&
      this.ngControl.invalid &&
      (this.ngControl.touched || this.ngControl.dirty) &&
      !this.readOnly
        ? 'error-field'
        : '',
        (this.isActive && !this.errorText) || (this.ngControl && this.ngControl.value?.length)
        ? 'active-field'
        : ''
    ].filter(Boolean);
  }
}

function cryptoRandom() {
  return Math.random().toString(36).slice(2);
}
